mod tests {
    use super::*;

    #[test]
    fn clippy_levels() {
        assert_eq!(
            severity_from_clippy("deny"),
            (Severity::High, Category::Correctness)
        );
        assert_eq!(
            severity_from_clippy("ERROR"),
            (Severity::High, Category::Correctness)
        );
        assert_eq!(
