            RunnerId::Gitleaks => RunnerId::Gitleaks,
            RunnerId::Jscpd => RunnerId::Jscpd,
            RunnerId::Lizard => RunnerId::Lizard,
            RunnerId::Semgrep => RunnerId::Semgrep,
            RunnerId::Zizmor => RunnerId::Zizmor,
        }
    }

    /// The trigger granularity of this runner.
    ///
    /// COARSE = project-wide: the tool inspects the whole project (or the whole
    /// crate / dependency tree) in one invocation and ignores any single changed
    /// file, so A3 runs it on the slow debounce ONCE per settle batch rather than
    /// per file. FINE = per-file: the tool is invoked with the changed file path
    /// and is cheap enough to run on every settled file.
    pub fn granularity(self) -> Granularity {
        match self {
            // Project-wide / crate-level / whole-tree scans.
            RunnerId::Clippy
            | RunnerId::CargoCheck
            | RunnerId::CargoAudit
            | RunnerId::CargoDeny
            | RunnerId::CargoFmt
            | RunnerId::Tsc
            | RunnerId::Knip
            | RunnerId::Jscpd
            | RunnerId::Gitleaks
            | RunnerId::NpmAudit
            | RunnerId::PipAudit
            // go vet COMPILES the module's packages (type-checked AST) → heavy /
            // thermal, project-wide; it is COARSE (debounced) and must never run in
            // the tight interactive loop (see runners/go_vet.rs header).
            | RunnerId::GoVet
            | RunnerId::Zizmor => Granularity::Coarse,
            // Per-file linters/scanners (invoked with the changed file path).
            RunnerId::Eslint
            | RunnerId::Prettier
            | RunnerId::Ruff
            | RunnerId::RuffFormat
            | RunnerId::Bandit
            | RunnerId::Vulture
            // gofmt only parses + reformats in memory (INSTANT, no compile) → Fine.
            | RunnerId::Gofmt
            // cppcheck is a no-compile static analyzer (parses the source directly,
            // never builds the TU), so it is cheap enough for the per-file loop → Fine.
            | RunnerId::Cppcheck
            // tidy is a single-binary HTML validator (no compile) → Fine (per-file).
            | RunnerId::Tidy
            // ktlint analyzes the Kotlin source directly (no compile-of-target) → Fine.
            | RunnerId::Ktlint
            // shellcheck/yamllint/sqlfluff are single-binary, no-compile linters → Fine.
            | RunnerId::Shellcheck
            | RunnerId::Yamllint
            | RunnerId::Sqlfluff
            // hadolint (Dockerfile)/actionlint (GH Actions)/stylelint (CSS) are
            // single-binary, no-compile linters → Fine (per-file).
            | RunnerId::Hadolint
            | RunnerId::Actionlint
            | RunnerId::Stylelint
            | RunnerId::Lizard
            | RunnerId::Semgrep
            | RunnerId::Oxlint
            | RunnerId::Pyright => Granularity::Fine,
        }
    }

    /// The tool's executable name, used for presence detection.
    pub fn program(self) -> &'static str {
        match self {
            RunnerId::Clippy | RunnerId::CargoCheck | RunnerId::CargoAudit | RunnerId::CargoFmt => "cargo",
            // cargo-deny ships as its own binary (a cargo subcommand shim).
            RunnerId::CargoDeny => "cargo-deny",
            RunnerId::Tsc => "tsc",
            RunnerId::Eslint => "eslint",
            RunnerId::Knip => "knip",
            RunnerId::Prettier => "prettier",
            RunnerId::NpmAudit => "npm",
            RunnerId::Oxlint => "oxlint",
            RunnerId::Ruff => "ruff",
            RunnerId::PipAudit => "pip-audit",
            RunnerId::Pyright => "pyright",
            RunnerId::RuffFormat => "ruff",
            RunnerId::Bandit => "bandit",
            RunnerId::Vulture => "vulture",
            RunnerId::Gofmt => "gofmt",
            RunnerId::GoVet => "go",
            RunnerId::Cppcheck => "cppcheck",
            RunnerId::Tidy => "tidy",
            RunnerId::Ktlint => "ktlint",
            RunnerId::Shellcheck => "shellcheck",
            RunnerId::Yamllint => "yamllint",
            RunnerId::Sqlfluff => "sqlfluff",
            RunnerId::Hadolint => "hadolint",
            RunnerId::Actionlint => "actionlint",
            RunnerId::Stylelint => "stylelint",
            RunnerId::Gitleaks => "gitleaks",
            RunnerId::Jscpd => "jscpd",
            RunnerId::Lizard => "lizard",
            RunnerId::Semgrep => "semgrep",
            RunnerId::Zizmor => "zizmor",
