/// What a runner is asked to inspect. Fine runners receive the changed file's
/// project-relative path; coarse runners ignore it and inspect the whole project.
#[derive(Debug, Clone)]
pub struct RunTarget {
    /// Project-relative path of the changed file (forward-slash normalized).
    /// Coarse (crate/project) runners ignore this.
    pub file_rel_path: String,
}

/// The cross-cutting runners that apply to EVERY file regardless of project kind
/// or language: secret scanning, copy/paste, complexity, semgrep, and zizmor.
const CROSS_CUTTING: [RunnerId; 5] = [
    RunnerId::Gitleaks,
    RunnerId::Jscpd,
    RunnerId::Lizard,
    RunnerId::Semgrep,
    RunnerId::Zizmor,
];

/// Decide which runners apply to a changed file, given the project's detected
/// kinds and the file's language. Deterministic and order-stable (kind-specific
/// runners first, then the cross-cutting set). The result never contains
/// duplicates.
///
/// Mapping:
///   - `.rs` file in a Rust project → clippy, cargo-check, cargo-audit (coarse)
///   - `.ts`/`.js` file in a Node project → tsc, eslint, knip
///   - `.py` file in a Python project → ruff, bandit, vulture
///   - `.go` file in a Go project → gofmt (fine), go vet (coarse, compile-based)
///   - `.c`/`.cpp`/... file in a C/C++ project → cppcheck (fine, no-compile)
///   - `.html`/`.htm` file (ANY project — HTML has no manifest) → tidy (fine, no-compile)
///   - `.kt`/`.kts` file in a Kotlin project → ktlint (fine, no-compile)
///   - `.sh`/`.bash`/... file (ANY project — shell has no manifest) → shellcheck (fine)
///   - `.yml`/`.yaml` file (ANY project — YAML has no manifest) → yamllint (fine)
///   - `.sql` file (ANY project — SQL has no manifest) → sqlfluff (fine)
///   - `Dockerfile`/`Containerfile`/`*.dockerfile` (ANY project — no manifest) → hadolint (fine)
///   - `.yml`/`.yaml` under `.github/workflows/` (ANY project) → actionlint (fine)
///   - `.css`/`.scss`/`.sass`/`.less` file (ANY project — CSS has no manifest) → stylelint (fine)
///   - ANY file → gitleaks, jscpd, lizard, semgrep (cross-cutting)
///
/// A language-specific runner is only added when BOTH the file lang AND the
/// matching project kind are present (a stray `.py` in a Rust-only repo gets only
/// the cross-cutting set — no point running ruff where there's no Python config).
/// HTML / Shell / YAML / SQL / Dockerfile / GithubActions / CSS are the deliberate
/// EXCEPTIONS: none has a canonical project manifest, so tidy / shellcheck / yamllint /
/// sqlfluff / hadolint / actionlint / stylelint gate on the FileLang ALONE (an
/// `.html`/`.sh`/`.yml`/`.sql`/`Dockerfile`/workflow/`.css` file anywhere is checkable,
/// like a standalone document).
pub fn applicable_runners(kinds: &HashSet<ProjectKind>, lang: FileLang) -> Vec<RunnerId> {
    let mut out: Vec<RunnerId> = Vec::new();
    match lang {
        FileLang::Rust if kinds.contains(&ProjectKind::Rust) => {
            out.push(RunnerId::Clippy);
            out.push(RunnerId::CargoCheck);
            out.push(RunnerId::CargoAudit);
            out.push(RunnerId::CargoDeny);
            out.push(RunnerId::CargoFmt);
        }
        FileLang::Ts if kinds.contains(&ProjectKind::Node) => {
            out.push(RunnerId::Tsc);
            out.push(RunnerId::Eslint);
            out.push(RunnerId::Knip);
            out.push(RunnerId::Prettier);
            out.push(RunnerId::NpmAudit);
            out.push(RunnerId::Oxlint);
        }
        FileLang::Py if kinds.contains(&ProjectKind::Python) => {
            out.push(RunnerId::Ruff);
            out.push(RunnerId::RuffFormat);
            out.push(RunnerId::PipAudit);
            out.push(RunnerId::Pyright);
            out.push(RunnerId::Bandit);
            out.push(RunnerId::Vulture);
        }
        FileLang::Go if kinds.contains(&ProjectKind::Go) => {
            // gofmt is Fine (instant, no compile); go vet is Coarse (compile-based,
            // debounced — never in the hot loop). Both advisory.
            out.push(RunnerId::Gofmt);
            out.push(RunnerId::GoVet);
        }
        FileLang::Cpp if kinds.contains(&ProjectKind::Cpp) => {
            // cppcheck is Fine (no-compile static analyzer, per-file). Advisory.
            out.push(RunnerId::Cppcheck);
        }
        // HTML has NO project manifest / ProjectKind — an `.html` file anywhere is
        // checkable, so tidy gates on the FileLang ALONE (deliberately no kind guard).
        FileLang::Html => {
            // tidy is Fine (single-binary HTML validator, per-file). Advisory.
            out.push(RunnerId::Tidy);
        }
        FileLang::Kotlin if kinds.contains(&ProjectKind::Kotlin) => {
            // ktlint is Fine (analyzes the source, no compile-of-target). Style/advisory.
            out.push(RunnerId::Ktlint);
        }
        // Shell/YAML/SQL have NO project manifest / ProjectKind (like HTML) — a
        // `.sh`/`.yml`/`.sql` file anywhere is checkable, so each runner gates on the
        // FileLang ALONE (deliberately no kind guard). All Fine (single-binary, no-compile).
        FileLang::Shell => {
            // shellcheck is Fine (single-binary shell analyzer). Advisory.
            out.push(RunnerId::Shellcheck);
        }
        FileLang::Yaml => {
            // yamllint is Fine (single-binary YAML linter). Advisory.
            out.push(RunnerId::Yamllint);
        }
        FileLang::Sql => {
            // sqlfluff is Fine (single-binary SQL linter). Style/advisory.
            out.push(RunnerId::Sqlfluff);
        }
        // Dockerfile/GithubActions/CSS have NO project manifest / ProjectKind (like HTML
        // and Shell/YAML/SQL) — a Dockerfile / a `.github/workflows/*.yml` / a `.css`
        // file anywhere is checkable, so each runner gates on the FileLang ALONE
        // (deliberately no kind guard). All Fine (single-binary, no-compile).
        FileLang::Dockerfile => {
            // hadolint is Fine (single-binary Dockerfile linter). Advisory.
            // (GPL-3.0 → INVOKE-ONLY, never bundled — see runners/hadolint.rs.)
            out.push(RunnerId::Hadolint);
        }
        FileLang::GithubActions => {
            // actionlint is Fine (single-binary workflow checker). Correctness/advisory.
            out.push(RunnerId::Actionlint);
        }
        FileLang::Css => {
            // stylelint is Fine (CSS linter). Advisory; only fires when a config exists.
            out.push(RunnerId::Stylelint);
        }
        _ => {}
    }
    out.extend_from_slice(&CROSS_CUTTING);
    out
}

/// Build a `Command` with `apply_no_window` already applied. EVERY runner spawns
/// through this helper so the CREATE_NO_WINDOW flag is set in exactly one place
/// (no per-runner re-inlining of `0x0800_0000`, no console flash on Windows).
pub fn build_command(program: &str) -> Command {
    // Resolve against the augmented PATH so a GUI-launched app (stripped PATH) still finds
    // Homebrew/npm/cargo tools; fall back to the bare name when unresolved (the command_exists
    // gate runs before this anyway).
    let resolved_path = crate::backend::provider_detect::resolve_program(program)
        .unwrap_or_else(|| std::path::PathBuf::from(program));
    let mut cmd = Command::new(&resolved_path);
    apply_no_window(&mut cmd);
    // Child sub-processes (cargo→rustc, npm→node, eslint plugins) inherit this PATH too.
    cmd.env("PATH", crate::backend::provider_detect::augmented_path());
    cmd
}

/// Default hard timeout for a single runner invocation. Compile/dependency-scan
/// tools (clippy/cargo-check/cargo-audit/semgrep) are slow; A3 passes a longer
/// budget for those via [`run_capture_with_timeout`]. The plain [`run_capture`]
/// uses this default.
pub const DEFAULT_RUNNER_TIMEOUT: Duration = Duration::from_secs(120);

/// Hard cap on the stdout we will read from a runner (16 MiB). A linter that
/// floods stdout (a pathological repo, a tool bug, or a hostile config) must not
/// be able to OOM the process: once the cap is hit we stop reading, kill the
/// child, and return nothing. Real linter JSON for a single file is kilobytes;
/// 16 MiB is generous headroom for an honest project-wide run.
pub const MAX_STDOUT_BYTES: usize = 16 * 1024 * 1024;

/// Shared single-line/truncation cap used by every parser to bound a title/body.
/// `max` is a CHAR count (not bytes), so multibyte text is never split mid-char
/// and the ellipsis is appended on overflow. Consolidated here so the ~12 runner
/// copies don't drift.
pub(super) fn cap(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        let truncated: String = s.chars().take(max).collect();
        format!("{truncated}…")
    }
}

/// Redact secret-looking tokens from a tool's human-readable message BEFORE it is
/// placed into a finding's title/body.
///
/// PRIVACY: several tools interpolate the MATCHED value into their `message` /
/// `Description` (semgrep expands `$METAVAR`; gitleaks can embed the match). Those
/// strings flow into the finding title/body, which is persisted to a shard — so a
/// raw secret would be written to disk. This pass replaces high-entropy / secret-
/// shaped runs with `[redacted]` while leaving ordinary prose (rule names, English
/// words, short identifiers, file paths) intact.
///
/// Heuristics (conservative — redact when in doubt, never panic):
///   - any run of 12+ chars drawn from the secret alphabet
///     (`A-Za-z0-9` plus the symbols common in tokens: `+/=_\-.`) that ALSO
///     contains at least one digit OR mixes upper+lower OR contains a token
///     symbol — i.e. it does not look like an ordinary lowercase English word; and
///   - AWS-access-key-shaped tokens (`AKIA`/`ASIA` + 16 base32 chars) regardless
///     of length classification.
///
/// A long all-lowercase word ("authentication") is NOT redacted; a base64/hex blob
/// or `AKIAIOSFODNN7EXAMPLE` IS. The scan is byte-cheap and allocation-light.
pub(super) fn redact_secrets(s: &str) -> String {
    const REDACTED: &str = "[redacted]";
    // A char is part of a candidate token if it's in the secret alphabet.
    fn is_token_char(c: char) -> bool {
        c.is_ascii_alphanumeric() || matches!(c, '+' | '/' | '=' | '_' | '-' | '.')
    }
    // Does a token look like a secret rather than ordinary prose / a path / a slug?
    fn looks_secret(tok: &str) -> bool {
        let len = tok.chars().count();
        if len < 12 {
            return false;
        }
        // AWS access key id: AKIA/ASIA + 16 uppercase base32 chars.
        if (tok.starts_with("AKIA") || tok.starts_with("ASIA"))
            && tok.len() == 20
            && tok[4..]
                .bytes()
                .all(|b| b.is_ascii_uppercase() || b.is_ascii_digit())
        {
            return true;
        }
        let has_digit = tok.chars().any(|c| c.is_ascii_digit());
        let has_upper = tok.chars().any(|c| c.is_ascii_uppercase());
        let has_lower = tok.chars().any(|c| c.is_ascii_lowercase());
        let has_symbol = tok
            .chars()
            .any(|c| matches!(c, '+' | '/' | '=' | '_' | '-' | '.'));
        // Dotted/dashed/underscored identifiers (rule ids, file paths like
        // `python.lang.security.audit`) are prose-ish: only flag them when they
        // also carry digits AND mixed case (i.e. a real token, not a slug).
        let mostly_separators = has_symbol && !has_digit && !(has_upper && has_lower);
        if mostly_separators {
            return false;
        }
        // High-entropy if it mixes classes: digits+letters, or upper+lower, or a
        // token symbol alongside alphanumerics.
        (has_digit && (has_upper || has_lower)) || (has_upper && has_lower) || has_symbol
    }

    let mut out = String::with_capacity(s.len());
    let mut token = String::new();
    let flush = |token: &mut String, out: &mut String| {
        if token.is_empty() {
            return;
        }
        if looks_secret(token) {
            out.push_str(REDACTED);
        } else {
            out.push_str(token);
        }
        token.clear();
    };
    for c in s.chars() {
        if is_token_char(c) {
            token.push(c);
        } else {
            flush(&mut token, &mut out);
            out.push(c);
        }
    }
    flush(&mut token, &mut out);
    out
}

/// Split a leading run of ASCII digits off `s`, returning `(digits, rest)`. Shared by
/// the coordinate parsers below so the digit-scan logic lives in exactly one place.
pub(super) fn take_digits(s: &str) -> (&str, &str) {
    let end = s
        .char_indices()
        .find(|(_, c)| !c.is_ascii_digit())
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    (&s[..end], &s[end..])
}

/// Anchor on the first `:<digits>:` (the file/line boundary) in a gcc/template-style
/// diagnostic line, returning `(file, line_no, remainder_after_the_first_colon-line-colon)`.
///
/// The split is deliberately NOT a blind `splitn(_, ':')`: a `file` may itself contain a
/// Windows drive colon (`C:\path\a.cpp`), so we scan from the LEFT for the FIRST `:` that
/// is immediately followed by `<digits>:`. Everything before that colon is the file, the
/// digit run is the line number, and the remainder is whatever follows the line's
/// trailing colon (a tool-specific tail such as `severity:id:message` for cppcheck, or a
/// further `<col>: message` triplet consumed by [`split_file_and_coord`]). `None` if no
/// such boundary exists or the digits don't parse to a `u32`.
pub(super) fn split_file_and_line(line: &str) -> Option<(&str, u32, &str)> {
    let bytes = line.as_bytes();
    let mut search_from = 0usize;
    while let Some(rel) = line[search_from..].find(':') {
        let colon = search_from + rel;
        let rest = &line[colon + 1..];
        // rest must begin with digits, then ':'.
        let (line_digits, after_line) = take_digits(rest);
        if !line_digits.is_empty() {
            if let Some(remainder) = after_line.strip_prefix(':') {
                if let Ok(n) = line_digits.parse::<u32>() {
                    let file = &line[..colon];
                    return Some((file, n, remainder));
                }
            }
        }
        // Advance past this colon (guard against a zero-width loop).
        search_from = colon + 1;
        if search_from >= bytes.len() {
            break;
        }
    }
    None
}

/// Anchor on the first `:<digits>:<digits>: ` coordinate triplet in a gcc/parsable-style
/// diagnostic line, returning `(file, line_no, col_no, remainder_after_the_triplet)`.
///
/// Builds on [`split_file_and_line`] (which already tolerates a Windows drive colon in the
/// file portion by scanning for the FIRST numeric `line:` boundary): after the `file:line:`
/// split, the remainder must itself begin with `<digits>:` (the column), and what follows
/// is returned with a single leading space trimmed (`"`: severity`" → "severity"`). If a
/// candidate `file:line:` boundary is NOT followed by a numeric column (e.g. cppcheck's
/// `file:line:severity:...`, where `severity` is non-numeric), we keep scanning for a LATER
/// boundary that does, so a line with no real `line:col` triplet → `None` rather than a
/// false match. `None` if no such triplet exists or the digits don't parse.
///
/// This is the ONE shared coordinate parser used by shellcheck / yamllint / actionlint /
/// ktlint (all of whose default reporters emit `file:line:col: …`).
pub(super) fn split_file_and_coord(line: &str) -> Option<(&str, u32, u32, &str)> {
    let bytes = line.as_bytes();
    let mut search_from = 0usize;
    // We can't reuse `split_file_and_line` directly in a loop because a non-numeric
    // column must let us keep scanning for a LATER boundary, so we inline the scan and
    // additionally require a numeric column after the line.
    while let Some(rel) = line[search_from..].find(':') {
        let colon = search_from + rel;
        let rest = &line[colon + 1..];
        let (line_digits, after_line) = take_digits(rest);
        if !line_digits.is_empty() {
            if let Some(after_line_colon) = after_line.strip_prefix(':') {
                let (col_digits, after_col) = take_digits(after_line_colon);
                if !col_digits.is_empty() {
                    if let Some(remainder) = after_col.strip_prefix(':') {
                        if let (Ok(l), Ok(c)) =
                            (line_digits.parse::<u32>(), col_digits.parse::<u32>())
                        {
                            let file = &line[..colon];
                            return Some((file, l, c, remainder.trim_start()));
                        }
                    }
                }
            }
        }
        search_from = colon + 1;
        if search_from >= bytes.len() {
            break;
        }
    }
    None
}

